import React from 'react';

function ListTasks({ tasks, onDelete }) {
    return (
        <ul>
            {tasks.map((task) => (
                <li key={task.id}>Task: {task.title} - {task.description}<button onClick={() => onDelete(task.id)}>Delete</button></li>
            ))}
        </ul>
    );
}

export default ListTasks;

