export const validateTaskForm = (task) => { 
return task.title.trim().length > 0 && task.description.trim().length > 0; 
};

export const validateEditTaskForm = (task, oldTask) => { 
return task.title.trim().length > 0 && task.description.trim().length > 0 && task.id == oldTask.id; 
};
